package studio.jiayu.neoagent;
import org.json.*;import java.util.*;
/** Device-local MCP JSON-RPC server/client. No listening socket, remote shell or model approval tool. */
final class DeviceMcp {
 static final String VERSION="2025-06-18";
 static final String[][] TOOLS={{"device.tap","tap","点击最新观察的节点或坐标"},{"device.long_press","long_press","长按最新观察的节点或坐标"},{"device.type","type","填写已授权输入框，通常最多500字符"},{"device.submit_search","submit_search","提交已读回核对的搜索词；系统输入法搜索可省略id，结果仍需观察"},{"device.swipe","swipe","在已授权应用公开区域滑动"},{"device.scroll","scroll","滚动当前可滚动区域"},{"device.back","back","返回当前应用上一层"},{"device.wait","wait","等待界面刷新"},{"device.observe","observe","重新获取本次应用授权范围内的原生观察"},{"document.write","document_write","在本任务新建文档的正文中写入你生成的完整文本，最多8000字符"},{"document.check","document_check","核对当前新建文档的正文与保存证据"},{"document.focus","document_focus","聚焦当前任务新建文档的正文"},{"document.replace","document_replace","替换当前任务正文中的唯一片段并完整读回"},{"purchase.check","purchase_check","核对本轮小额购买的原生金额与订单状态"},{"purchase.submit","purchase_submit","原生订单明细完整且原始用户授权时提交唯一订单"},{"purchase.pay","purchase_pay","原生金额及本轮订单身份已核验时付款"},{"skills.list","skills_list","列出设备内可用技能"},{"skills.read","skills_read","读取指定的内置技能"}};
 final ControlService owner;int requests,toolCalls;String lastTool="";boolean initialized,negotiated;
 DeviceMcp(ControlService s){owner=s;}
 void reset(){requests=0;toolCalls=0;lastTool="";initialized=false;negotiated=false;}
 static boolean mutation(String action){return !java.util.Arrays.asList("observe","wait","skills_list","skills_read","document_check","purchase_check").contains(action);}
 static String actionFor(String tool){for(String[] t:TOOLS)if(t[0].equals(tool))return t[1];return "";}
 static String toolFor(String action){for(String[] t:TOOLS)if(t[1].equals(action))return t[0];return "";}
 static JSONObject properties(String action)throws Exception{JSONObject p=new JSONObject().put("memory",new JSONObject().put("type","string").put("maxLength",TaskMemory.MAX));if(action.equals("tap")||action.equals("long_press"))p.put("id",new JSONObject().put("type","integer")).put("x",new JSONObject().put("type","integer").put("minimum",0).put("maximum",1000)).put("y",new JSONObject().put("type","integer").put("minimum",0).put("maximum",1000));if(action.equals("type")||action.equals("submit_search")||action.equals("purchase_submit")||action.equals("purchase_pay"))p.put("id",new JSONObject().put("type","integer"));if(action.equals("type")||action.equals("document_write"))p.put("text",new JSONObject().put("type","string").put("maxLength",action.equals("type")?500:8000));if(action.equals("document_replace"))for(String key:new String[]{"find","replacement"})p.put(key,new JSONObject().put("type","string").put("maxLength",2000));if(action.equals("skills_read"))p.put("id",new JSONObject().put("type","string").put("enum",new JSONArray(DeviceSkills.IDS)));if(action.equals("scroll"))p.put("direction",new JSONObject().put("type","string").put("enum",new JSONArray().put("up").put("down")));if(action.equals("swipe"))for(String k:new String[]{"x","y","x2","y2"})p.put(k,new JSONObject().put("type","integer").put("minimum",0).put("maximum",1000));return p;}
 static JSONArray catalog()throws Exception{JSONArray list=new JSONArray();for(String[] t:TOOLS){JSONObject schema=new JSONObject().put("type","object").put("properties",properties(t[1])).put("additionalProperties",false);if(t[1].equals("document_write")||t[1].equals("type"))schema.put("required",new JSONArray().put("text"));if(t[1].equals("document_replace"))schema.put("required",new JSONArray().put("find").put("replacement"));if(t[1].equals("tap")||t[1].equals("long_press"))schema.put("anyOf",new JSONArray().put(new JSONObject().put("required",new JSONArray().put("id"))).put(new JSONObject().put("required",new JSONArray().put("x").put("y"))));if(t[1].equals("skills_read")||t[1].equals("purchase_submit")||t[1].equals("purchase_pay"))schema.put("required",new JSONArray().put("id"));if(t[1].equals("swipe"))schema.put("required",new JSONArray().put("x").put("y").put("x2").put("y2"));list.put(new JSONObject().put("name",t[0]).put("description",t[2]).put("inputSchema",schema));}return list;}
 JSONObject rpc(JSONObject request,long g)throws Exception{return rpc(request,g,owner.currentObservation);}
 JSONObject rpc(JSONObject request,long g,ControlService.Observation source)throws Exception{try{return dispatch(request,g,source);}catch(org.json.JSONException invalid){return error(request.opt("id"),-32602,"Invalid method parameters");}}
 JSONObject dispatch(JSONObject request,long g,ControlService.Observation source)throws Exception{requests++;Object id=request.opt("id");String method=request.optString("method");if(!"2.0".equals(request.optString("jsonrpc")))return error(id,-32600,"Invalid JSON-RPC version");if(method.equals("notifications/initialized")){if(negotiated&&!request.has("id"))initialized=true;return null;}if(!request.has("id"))return error(null,-32600,"Requests require an id");if(id instanceof JSONObject||id instanceof JSONArray)return error(null,-32600,"Invalid request id");JSONObject result;
  if(method.equals("initialize")){JSONObject init=request.optJSONObject("params");if(init==null||init.optString("protocolVersion").isEmpty()||init.optJSONObject("clientInfo")==null||init.optJSONObject("capabilities")==null)return error(id,-32602,"Invalid initialization parameters");negotiated=true;initialized=false;result=new JSONObject().put("protocolVersion",VERSION).put("capabilities",new JSONObject().put("tools",new JSONObject().put("listChanged",false)).put("resources",new JSONObject().put("listChanged",false))).put("serverInfo",new JSONObject().put("name","Neo Agent Touch Device Tools").put("version","0.1.15-beta.1"));}
  else if(method.equals("ping"))result=new JSONObject();
  else if(!initialized)return error(id,-32002,"MCP session not initialized");
  else if(method.equals("tools/list"))result=new JSONObject().put("tools",catalog());
  else if(method.equals("resources/list")){JSONArray resources=new JSONArray();for(String skill:DeviceSkills.IDS)resources.put(new JSONObject().put("uri","neo-skill://"+skill).put("name",skill).put("mimeType","text/markdown"));result=new JSONObject().put("resources",resources);}
  else if(method.equals("resources/read")){String uri=request.getJSONObject("params").getString("uri");if(!uri.startsWith("neo-skill://")||!DeviceSkills.known(uri.substring(12)))return error(id,-32602,"Unknown skill resource");result=new JSONObject().put("contents",new JSONArray().put(new JSONObject().put("uri",uri).put("mimeType","text/markdown").put("text",DeviceSkills.read(owner,uri.substring(12)))));}
  else if(method.equals("tools/call")){JSONObject params=request.optJSONObject("params");String name=params==null?"":params.optString("name"),action=actionFor(name);if(action.isEmpty())return error(id,-32602,"Unknown tool");JSONObject args=params.optJSONObject("arguments");if(args==null)args=new JSONObject();try{validate(action,args);}catch(Exception invalid){return error(id,-32602,"Invalid tool arguments");}try{owner.check(g);toolCalls++;lastTool=name;JSONObject command=new JSONObject(args.toString()).put("action",action);String receipt;
    if(action.equals("skills_list"))receipt=DeviceSkills.list().toString();else if(action.equals("skills_read"))receipt=DeviceSkills.read(owner,args.getString("id"));else if(action.equals("observe"))receipt=owner.observe(owner.runConfig.vision,g).json.toString();else receipt=owner.execute(new Action(command),g,source);
    result=new JSONObject().put("content",new JSONArray().put(new JSONObject().put("type","text").put("text",receipt))).put("structuredContent",new JSONObject().put("ok",true).put("tool",name)).put("isError",false);
   }catch(Exception failure){result=new JSONObject().put("content",new JSONArray().put(new JSONObject().put("type","text").put("text",ControlService.safeError(failure)))).put("structuredContent",new JSONObject().put("ok",false).put("tool",name).put("errorCategory",errorCategory(failure))).put("isError",true);}}
  else return error(id,-32601,"Unknown method");return new JSONObject().put("jsonrpc","2.0").put("id",id==null?JSONObject.NULL:id).put("result",result);
 }
 static void validate(String action,JSONObject args)throws Exception{JSONObject allowed=properties(action);Iterator<String> keys=args.keys();while(keys.hasNext()){String key=keys.next();if(!allowed.has(key))throw new ActionEnvelopeRules.Invalid("argument_unknown",key);JSONObject schema=allowed.getJSONObject(key);Object value=args.get(key);if(schema.optString("type").equals("integer")&&(!(value instanceof Number)||!Double.isFinite(((Number)value).doubleValue())||((Number)value).doubleValue()!=Math.rint(((Number)value).doubleValue())))throw new ActionEnvelopeRules.Invalid("argument_type",key);if(schema.optString("type").equals("string")&&!(value instanceof String))throw new ActionEnvelopeRules.Invalid("argument_type",key);if(schema.has("enum")){boolean match=false;JSONArray values=schema.getJSONArray("enum");for(int i=0;i<values.length();i++)if(values.get(i).equals(value))match=true;if(!match)throw new ActionEnvelopeRules.Invalid("argument_type",key);}}if(action.equals("skills_read")){if(!DeviceSkills.known(args.getString("id")))throw new Exception("未知技能");return;}if(action.equals("document_write")){String text=args.getString("text");if(text.isEmpty()||text.length()>8000)throw new Exception("正文输入长度不在允许范围");return;}if(action.equals("skills_list")||action.equals("observe"))return;new Action(new JSONObject(args.toString()).put("action",action));}
 static String errorCategory(Exception failure){return failure instanceof ControlService.UiChangedException?"transient_ui":failure instanceof ControlService.KeyboardOcclusionException?"keyboard_occlusion":failure instanceof ControlService.CaptureRetryException?"capture_retry":failure instanceof ControlService.LocalBoundaryException?"local_boundary":"tool_failure";}
 static Exception toolFailure(JSONObject result,String receipt){JSONObject detail=result.optJSONObject("structuredContent");String kind=detail==null?"":detail.optString("errorCategory");if(kind.equals("transient_ui"))return new ControlService.UiChangedException();if(kind.equals("keyboard_occlusion"))return new ControlService.KeyboardOcclusionException();if(kind.equals("capture_retry"))return new ControlService.CaptureRetryException();if(kind.equals("local_boundary"))return new ControlService.LocalBoundaryException(receipt);return new Exception(receipt);}
 static JSONObject error(Object id,int code,String message)throws Exception{return new JSONObject().put("jsonrpc","2.0").put("id",id==null?JSONObject.NULL:id).put("error",new JSONObject().put("code",code).put("message",message));}
 String activate(String pkg,long g)throws Exception{if(!initialized){rpc(new JSONObject().put("jsonrpc","2.0").put("id",requests+1).put("method","initialize").put("params",new JSONObject().put("protocolVersion",VERSION).put("capabilities",new JSONObject()).put("clientInfo",new JSONObject().put("name","Neo Agent Touch").put("version","0.1.15-beta.1"))),g);rpc(new JSONObject().put("jsonrpc","2.0").put("method","notifications/initialized"),g);}JSONObject list=rpc(new JSONObject().put("jsonrpc","2.0").put("id",requests+1).put("method","tools/list"),g);StringBuilder context=new StringBuilder("\n本机MCP工具目录：").append(list.getJSONObject("result").toString()).append("\n可输出 {\"jsonrpc\":\"2.0\",\"id\":1,\"method\":\"tools/call\",\"params\":{\"name\":\"device.tap\",\"arguments\":{\"id\":1}}}。完成和需本人处理时仍输出finish或ask动作。\n自动加载的可信技能：\n");for(String id:DeviceSkills.select(pkg,GameplayIntent.play(owner.activeRequest==null?owner.task:owner.activeRequest.original))){JSONObject response=rpc(new JSONObject().put("jsonrpc","2.0").put("id",requests+1).put("method","resources/read").put("params",new JSONObject().put("uri","neo-skill://"+id)),g);context.append(response.getJSONObject("result").getJSONArray("contents").getJSONObject(0).getString("text")).append('\n');}context.append("\n").append(new AppAccess(owner).guidance(pkg));return context.toString();}
 static Action decode(String raw)throws Exception{JSONObject o=Action.object(raw);if(!o.has("jsonrpc")){String mapped=actionFor(o.optString("action"));if(!mapped.isEmpty())o.put("action",mapped);if(o.has("name")&&o.has("arguments")){String named=actionFor(o.optString("name"));if(named.isEmpty())throw new ActionEnvelopeRules.Invalid("tool_unknown","name");JSONObject arguments=o.getJSONObject("arguments");validate(named,arguments);return new Action(new JSONObject(arguments.toString()).put("action",named));}Action legacy=new Action(o);if(!toolFor(legacy.name).isEmpty()){JSONObject arguments=new JSONObject(legacy.data.toString());arguments.remove("action");validate(legacy.name,arguments);}return legacy;}if(!o.has("id")||o.opt("id") instanceof JSONObject||o.opt("id") instanceof JSONArray||!o.optString("jsonrpc").equals("2.0")||!o.optString("method").equals("tools/call"))throw new ActionEnvelopeRules.Invalid("envelope_field","jsonrpc");JSONObject p=o.getJSONObject("params");String action=actionFor(p.getString("name"));if(action.isEmpty())throw new ActionEnvelopeRules.Invalid("tool_unknown","name");JSONObject args=p.optJSONObject("arguments");if(args==null)args=new JSONObject();validate(action,args);return new Action(new JSONObject(args.toString()).put("action",action));}
 String invoke(Action a,long g,ControlService.Observation source)throws Exception{String name=toolFor(a.name);if(name.isEmpty())throw new Exception("动作没有对应本机工具");JSONObject args=new JSONObject(a.data.toString());args.remove("action");JSONObject response=rpc(new JSONObject().put("jsonrpc","2.0").put("id",requests+1).put("method","tools/call").put("params",new JSONObject().put("name",name).put("arguments",args)),g,source);if(response.has("error"))throw new Exception(response.getJSONObject("error").getString("message"));JSONObject result=response.getJSONObject("result");String receipt=result.getJSONArray("content").getJSONObject(0).getString("text");if(result.optBoolean("isError"))throw toolFailure(result,receipt);return a.name.equals("observe")?"已重新观察当前应用；下一步以新截图及系统映射为准":receipt;}
 JSONObject status()throws Exception{return new JSONObject().put("initialized",initialized).put("transport","in-process JSON-RPC").put("protocolVersion",VERSION).put("requests",requests).put("toolCalls",toolCalls).put("lastTool",lastTool).put("external_listener",false);}
}
